        if (i != 0) {
          app.append('\n');
        }
      } else {
        app.append(' ');
      }
      byte b = bytes[i];
      app.append("0123456789ABCDEF".charAt((b >>> 4) & 0xf));
      app.append("0123456789ABCDEF".charAt((b >>> 0) & 0xf));
    }
  }

