					if (buildInfoVersion.getMicro() > version.getMicro())
						compatible = true;
					if (buildInfoVersion.getMicro() < version.getMicro())
						compatible = false;
					if (buildInfoVersion.getQualifier().compareTo(version.getQualifier()) >= 0)
