                    if (!registeredBefore) {
                        if (routeClass.verifyLogin()) {
                            server.before(routeInfo.url(), ctx -> {
                                if (routeClass.verifyLogin()) {
                                    if (!Route.verifyLogin(ctx)) {
                                        throw new RouteLoaderException();
                                    }
                                }
                            });
                        }

